#!/usr/bin/env bash
# Correctifs du domaine : dossiers figés à la création (MIGRATION storage_segments), brouillons qui ne
# fuient plus par leurs créneaux/séances/liens, plus d'e-mail sur les fiches publiques, hiérarchie des
# instructeurs, « fin après début » sur le résultat, séances du jour gardées par l'agenda, catch journalisés.
# Prérequis : apply-docs-auth.sh. Contient une migration → voir le message final.
# Usage (racine du repo) : bash apply-fix-domaine.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"packages/backend/src/modules/storage/storageSegments.ts" 2>/dev/null | grep -qF "ensureStorageSegments"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "La vue d’ensemble, et les pièges" "apps/web/content/docs/dev/auth/vue-d-ensemble.mdx" 2>/dev/null || { echo "❌ lancer d'abord apply-docs-auth.sh"; exit 1; }
